const input = require("fs").readFileSync(0, "utf8");

function gcd(a, b) {
  while (b !== 0) {
    const r = a % b;
    a = b;
    b = r;
  }
  return a;
}

const [a, b] = input.trim().split(/\s+/).map(Number);
console.log(gcd(a, b));

